int64_t total = 0;
while (true) {
  nsCOMPtr<nsIFile> f;
  rv = dirEnumerator->GetNextFile(getter_AddRefs(f));
  NS_ENSURE_SUCCESS(rv, rv);
  if (!f) {
    break;  // No more files.
  }

  // Shouldn't have any subdirs in here, but if we do, skip 'em.
  bool isDir;
  rv = f->IsDirectory(&isDir);
  NS_ENSURE_SUCCESS(rv, rv);
  if (isDir) {
    continue;
  }

  int64_t s;
  rv = f->GetFileSize(&s);
  NS_ENSURE_SUCCESS(rv, rv);
  total += s;
}
*size = total;
return NS_OK;
